const scheduleDeliveries = `-- name: ScheduleDeliveries :many
SELECT id FROM scheduler_deliveries WHERE schedule_arn=? ORDER BY id
`

func (q *Queries) ScheduleDeliveries(ctx context.Context, scheduleArn string) ([]string, error) {
	rows, err := q.db.QueryContext(ctx, scheduleDeliveries, scheduleArn)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []string{}
	for rows.Next() {
		var id string
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
